con:config.script:
// Get response
def response = context.expand('${Retrieve Job Security Group#Response}')
log.info response

def json = new groovy.json.JsonSlurper().parseText(response)

// Take the first href
def href = json.items[0].links[0].href

// Extract ID (after last '/')
def id = href.tokenize('/')[-1]

// Store in property for later use
context.testCase.setPropertyValue("UniqueId", id)

log.info "Extracted ID: " + id

